<body>

<!-- Slideshow -->
<div id="flashSequence" class="cst-stage">
  <img src="https://c-studios.co.uk/wp-content/uploads/2025/09/Screenshot-2025-05-20-at-20.46.54-e1757634835112.png" data-desktop="https://c-studios.co.uk/wp-content/uploads/2025/06/Screenshot-2025-05-20-at-20.46.54.webp"  class="flash-img" loading="lazy" decoding="async" />
