  <img src='https://c-studios.co.uk/wp-content/uploads/2025/09/nism.info_1715258179_3364151898821329457_58206187637-e1757634940306.jpg' data-desktop="https://c-studios.co.uk/wp-content/uploads/2025/06/nism.info_1715258179_3364151898821329457_58206187637-e1755061369408.webp"  class="flash-img" loading="lazy" decoding="async" />
  <img  src="https://c-studios.co.uk/wp-content/uploads/2025/09/cynthia.ii_1736872733_3545467916234468349_1523711075-e1757633988294.jpg"  data-desktop="https://c-studios.co.uk/wp-content/uploads/2025/06/cynthia.ii_1736872733_3545467916234468349_1523711075.webp"class="flash-img" loading="lazy" decoding="async" />
  <img   src="https://c-studios.co.uk/wp-content/uploads/2025/08/IMG_5311.jpg" data-desktop="https://c-studios.co.uk/wp-content/uploads/2025/06/cynthia.ii_1736872733_3545467916234468349_1523711075.webp" class="flash-img" loading="lazy" decoding="async" />
  <img src="https://c-studios.co.uk/wp-content/uploads/2025/06/cynthia.ii_1719068682_3396116710752996930_1523711075-copy-e1755061791814.webp" class="flash-img" loading="lazy" decoding="async" />
  <img src="https://c-studios.co.uk/wp-content/uploads/2025/06/cynthia.ii_1733047937_3513383204309688443_1523711075.webp" class="flash-img" loading="lazy" decoding="async" />
  <img src="https://c-studios.co.uk/wp-content/uploads/2025/06/pasted-image.webp" class="flash-img" loading="lazy" decoding="async" />
</div>

<div class="cst-hero" id="cstHero">
  <!-- Moon (tracker) -->
  <div class="moon"></div>

  <!-- Text -->
  <div class="container" id="textContainer">
    <p class="home-text">C-STUDIOS</p>
    <p class="sub-text" id="subText">
      is a creative strategy studio working across cultural research, concepts, creative direction, consulting, and curation.
    </p>
  </div>

  <!-- Inverted mask + matching rim -->
  <div id="revealHole" class="reveal-hole" aria-hidden="true"></div>
  <div id="holeRim" class="hole-rim" aria-hidden="true"></div>
</div>

<style>
:root { --vh: 1vh; }

/* ORIGINAL STYLES - KEEP EVERYTHING THE SAME */
.container, .home-text, .sub-text, .moon, .flash-img { 
  will-change: transform, opacity; 
  backface-visibility: hidden;
}

/* Base layout */
#cstHero { 
  position: relative; 
  width: 100vw; 
  height: calc(var(--vh) * 100); 
  overflow: hidden; 
  background: white; 
}

.cst-stage { 
  position: absolute; 
  inset: 0; 
  width: 100vw; 
  height: calc(var(--vh) * 100); 
  z-index: 0; 
}

/* SLIDESHOW FIX: Ensure images are visible and positioned correctly */
.flash-img { 
  position: absolute !important; 
  top: 0 !important;
  left: 0 !important;
  width: 100vw !important; 
  height: calc(var(--vh) * 100) !important; 
  object-fit: cover !important; 
  object-position: center top !important; /* Align to top, center horizontally */
  opacity: 0 !important; 
  transition: opacity 1.2s ease-in-out !important; 
  transform: scale(1) !important; 
  z-index: 0;
  display: block !important; /* Ensure they're displayed */
  visibility: visible !important; /* Ensure they're visible */
  margin: 0 !important; /* Remove any margins */
  padding: 0 !important; /* Remove any padding */
  border: none !important; /* Remove any borders */
  max-width: none !important; /* Override max-width constraints */
  max-height: none !important; /* Override max-height constraints */
  min-width: 100vw !important; /* Force minimum width */
  min-height: calc(var(--vh) * 100) !important; /* Force minimum height */
}

.flash-img.active { 
  opacity: 1 !important; 
  transform: scale(1) !important; /* No zoom - stay at normal size */
  z-index: 1; /* Bring active image forward */
}

/* Slideshow overlay - separate div element */
.slideshow-overlay {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  background: rgba(0, 0, 0, 0.3) !important; /* Even darker for testing */
  pointer-events: none !important;
  z-index: 5 !important; /* Higher z-index - above images (0-1) and their active state */
  opacity: 0 !important; /* Start hidden */
  transition: opacity 1.2s ease-in-out !important;
  display: block !important;
  visibility: visible !important;
}

/* Show overlay when slideshow is active */
.slideshow-overlay.active {
  opacity: 1 !important;
}

@supports (height: 100svh) {
  #cstHero, .cst-stage, .flash-img { height: 100svh; }
}
@supports (height: 100dvh) {
  #cstHero, .cst-stage, .flash-img { height: 100dvh; }
}

/* Text block - KEEP ORIGINAL */
.container {
  position: absolute; 
  top: 50%; 
  left: 93vw; 
  transform: translateY(-50%); 
  white-space: nowrap; 
  opacity: 1; 
  z-index: 10;
  display: flex; 
  align-items: center; 
  gap: 0; 
  flex-wrap: nowrap;
}

.text-centered { 
  left: 50% !important; 
  transform: translate(-50%, -50%) !important; 
  justify-content: center; 
  text-align: center; 
}

.home-text, .sub-text {
  margin: 0; 
  white-space: nowrap; 
  text-transform: uppercase;
  font: 400 16px/1.2 'Helvetica Neue', Helvetica, Arial, sans-serif !important; 
  opacity: 0;
}

.home-text { 
  transform: translateX(-100vw); 
  animation: slideInLeft 2.5s cubic-bezier(0.645, 0.045, 0.355, 1) forwards; 
  margin-right: 8px; 
}

@keyframes slideInLeft { 
  to { 
    transform: translateX(0); 
    opacity: 1; 
  } 
}

.sub-text span { 
  font: inherit !important; 
  line-height: inherit !important; 
  letter-spacing: inherit !important; 
  display: inline !important; 
}

/* Moon - KEEP ORIGINAL */
.moon {
  background: transparent;
  position: absolute; 
  top: 50%; 
  left: 100vw;
  width: calc(var(--vh) * 95); 
  height: calc(var(--vh) * 95);
  border-radius: 50%; 
  transform: translateY(-50%); 
  z-index: 5;
  transition: transform 2.5s cubic-bezier(0.645, 0.045, 0.355, 1), opacity 1s ease-in;
  opacity: 1;
}

@supports (height: 100svh) { .moon { width: 95svh; height: 95svh; } }
@supports (height: 100dvh) { .moon { width: 95dvh; height: 95dvh; } }

/* Mask layers - KEEP ORIGINAL */
.reveal-hole {
  position: absolute; 
  inset: 0; 
  background: #fff; 
  z-index: 25; 
  pointer-events: none;
  opacity: 1; 
  transition: opacity .6s ease;
  --mx: 120vw; 
  --my: 50vh; 
  --mr: 0px;
  -webkit-mask: radial-gradient(circle var(--mr) at var(--mx) var(--my), transparent 98%, #000 100%);
          mask: radial-gradient(circle var(--mr) at var(--mx) var(--my), transparent 98%, #000 100%);
}

.hole-rim {
  position: absolute; 
  left: 0; 
  top: 0; 
  width: 0; 
  height: 0; 
  z-index: 26; 
  pointer-events: none; 
  border-radius: 50%;
  opacity: 1; 
  transition: opacity .6s ease;
  box-shadow:
    inset 8px 8px 12px rgba(0,0,0,0.25),
    inset -4px -4px 8px rgba(255,255,255,0.9);
}

/* Mobile - KEEP ALL ORIGINAL */
@media (max-width: 767px) {
  #cstHero, .cst-stage, .flash-img 
  { height: calc(var(--vh) * 100) !important; }

  .moon { 
    width: calc(var(--vh) * 75) !important; 
    height: calc(var(--vh) * 75) !important; 
    left: 100vw; 
  }

  #cstHero .container.text-centered {
    left: 5vw !important; 
    transform: translateY(-50%) !important; 
    justify-content: flex-start !important; 
    text-align: left !important; 
  }

  .home-text, .sub-text {
    font-size: 0.7em !important;
    line-height: 1.25 !important;
    white-space: normal !important;
  }

  .sub-text { 
    visibility: hidden; 
  }

  .sub-text .line { 
    display: block; 
  }

  #cstHero .container {
    width: calc(100vw - 52px);
    color: white;
    display: block !important;
    left: 26px !important;
    top: 40vh !important;
    transform: none !important;
    z-index: 30 !important;
    align-items: flex-start !important;
  }

  .home-text {
    float: left;
    white-space: nowrap !important;
    margin: 0 8px 0 0 !important;
    line-height: 1.25 !important;
    font-size: 0.65rem !important;
  }

  .sub-text {
    display: block;
    white-space: normal !important;
    font-size: 0.65rem !important;
    line-height: 1.25 !important;
  }

  #cstHero .container::after { 
    content: ""; 
    display: block; 
    clear: both; 
  }

  #cstHero { 
    isolation: isolate; 
  }

  .home-text, .sub-text {
    color: white;
    text-shadow: none !important;
    -webkit-text-stroke: 0 !important;
  }

  /* Mobile slideshow fixes */
  .flash-img {
    height: calc(var(--vh) * 100) !important;
    min-height: calc(var(--vh) * 100) !important;
  }
}

/* Desktop - KEEP ORIGINAL */
@media (min-width: 768px) {
  .sub-text {
    opacity: 0;
    transform: translateX(20vw);
    animation: slideInLeft 2s cubic-bezier(0.645,0.045,0.355,1) 1.5s forwards;
  }
}

@media (min-width: 768px) {
  #textContainer {
    transition: left 1200ms cubic-bezier(0.22,1,0.36,1),
                transform 1200ms cubic-bezier(0.22,1,0.36,1);
  }
}

#cstHero { 
  isolation: isolate; 
}

.cst-stage { 
  position: absolute; 
  inset: 0; 
  z-index: 0; 
}

.cst-stage::after {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.25);
  pointer-events: none;
  z-index: 1;
  opacity: 0;
  transition: opacity .35s ease;
}

/* Show overlay when slideshow has active images */
.cst-stage:has(.flash-img.active)::after { 
  opacity: 1; 
}

.home-text, .sub-text {
  color: lightgrey;
  transition: color .3s ease;
}

#cstHero:has(.flash-img.active) .home-text,
#cstHero:has(.flash-img.active) .sub-text {
  color: #fff;
}
</style>

<script>

// KEEP ALL ORIGINAL FUNCTIONS - JUST FIX SLIDESHOW

function prepareMobileSubtextEarly() {
  const isPhone = window.matchMedia('(max-width: 767px)').matches;
  if (!isPhone) return;

  const sub = document.getElementById('subText');
  if (!sub) return;

  sub.innerHTML =
    '<span class="line">IS A CREATIVE STRATEGY STUDIO </span>' +
    '<span class="line">WORKING ACROSS CULTURAL RESEARCH, </span>' +
    '<span class="line">CONCEPTS, CREATIVE DIRECTION, CONSULTING, AND CURATION.</span>';

  sub.style.opacity = '0';
  sub.style.transform = 'translateX(140vw)';
  sub.style.visibility = 'hidden';
}

function swapMobileImages() {
  if (!window.matchMedia('(max-width: 767px)').matches) return;

  // Preload mobile images for faster switching
  const mobileUrls = [];

  document.querySelectorAll('#flashSequence .flash-img').forEach(img => {
    const m = img.getAttribute('data-mobile');
    if (m && img.src !== m) {
      mobileUrls.push(m);
      img.src = m;
      // Add loading priority for mobile
      img.loading = 'eager';
    }
  });

  // Preload next few mobile images
  mobileUrls.slice(0, 3).forEach(url => {
    const preloadImg = new Image();
    preloadImg.src = url;
  });

  console.log('📱 Swapped to mobile images and preloaded first 3');
}

function setRealVH() {
  // Optimize for mobile performance
  const vh = window.innerHeight * 0.01;
  document.documentElement.style.setProperty('--vh', `${vh}px`);

  // Mobile-specific optimizations
  if (window.innerWidth <= 767) {
    // Reduce unnecessary repaints on mobile
    document.body.style.overflow = 'hidden';
    // Force GPU acceleration for mobile
    document.documentElement.style.transform = 'translateZ(0)';
  }
}

(function fixElementorWrappers() {
  const hero = document.getElementById('cstHero');
  if (!hero) return;
  const widget = hero.closest('.elementor-widget-container');
  if (widget) Object.assign(widget.style, { position: 'relative', padding: '0', height: 'auto', minHeight: '0' });
  const section = hero.closest('.elementor-section');
  if (section) { section.style.minHeight = '100dvh'; section.style.padding = '0'; }
})();

function syncHoleToMoon(durationMs = 5000) {
  const moon = document.querySelector('.moon');
  const hole = document.getElementById('revealHole');
  const rim = document.getElementById('holeRim');

  let start = performance.now();
  function tick(now) {
    const r = moon.getBoundingClientRect();
    const cx = r.left + r.width/2;
    const cy = r.top + r.height/2;
    const radius = r.width/2;

    hole.style.setProperty('--mx', cx + 'px');
    hole.style.setProperty('--my', cy + 'px');
    hole.style.setProperty('--mr', radius + 'px');

    rim.style.width = r.width + 'px';
    rim.style.height = r.height + 'px';
    rim.style.left = (cx - radius) + 'px';
    rim.style.top = (cy - radius) + 'px';

    if (now - start < durationMs) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}

if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
window.onbeforeunload = () => window.scrollTo(0, 0);
window.scrollTo(0, 0);

// FIXED SLIDESHOW FUNCTION - Force fade with direct styles + smooth looping
function startSlideshow() {
  const images = document.querySelectorAll('#flashSequence .flash-img');
  console.log('🎬 SLIDESHOW: Found', images.length, 'images');

  if (!images.length) {
    console.error('❌ SLIDESHOW: No images found!');
    return;
  }

// Force all images to start with proper styles
  images.forEach((img, index) => {
    // Use modern viewport units for mobile compatibility
    const isMobile = window.innerWidth <= 767;
    const heightValue = isMobile ? 'calc(var(--vh) * 100)' : '100vh';

    img.style.cssText += `
      opacity: 0 !important; 
      transition: opacity 1.2s ease-in-out !important; 
      z-index: 0 !important;
      position: absolute !important;
      top: 0 !important;
      left: 0 !important;
      width: 100vw !important;
      height: ${heightValue} !important;
      object-fit: cover !important;
      object-position: center top !important;
      margin: 0 !important;
      padding: 0 !important;
      border: none !important;
      max-width: none !important;
      max-height: none !important;
      min-width: 100vw !important;
      min-height: ${heightValue} !important;
      transform: scale(1) !important;
    `;
  });

  let current = 0;

  // Force first image to be visible
  images[current].style.cssText += 'opacity: 1 !important; z-index: 1 !important;';
  images[current].classList.add('active'); // Add class for CSS :has() selector
  console.log('✅ SLIDESHOW: Activated image', current + 1);

  const slideInterval = setInterval(() => {
    const prev = current;

    // Calculate next image with smooth looping
    current = (current + 1) % images.length;

    // Smooth transition for all slides including loop
    console.log(`🔄 SLIDESHOW: ${prev + 1} → ${current + 1}`);

    // Start fading in next image
    images[current].style.cssText += 'opacity: 1 !important; z-index: 1 !important;';
    images[current].classList.add('active'); // Ensure CSS class is added

    // Start fading out previous image with consistent timing
    setTimeout(() => {
      images[prev].style.cssText += 'opacity: 0 !important; z-index: 0 !important;';
      images[prev].classList.remove('active'); // Remove CSS class
      console.log(`✅ SLIDESHOW: Image ${current + 1} faded in, ${prev + 1} faded out`);
    }, 600); // Consistent 600ms overlap for all transitions

  }, 1200);

  console.log('🎬 SLIDESHOW: Interval started with forced fade animations and smooth looping');
  return slideInterval;
}

// KEEP ALL ORIGINAL ANIMATION SEQUENCE
setTimeout(() => {
  prepareMobileSubtextEarly();
  swapMobileImages();
  setRealVH();

  const moon = document.querySelector('.moon');
  const container = document.getElementById('textContainer');
  const subText = document.getElementById('subText');

  syncHoleToMoon(5200);
  const overhangRatio = (window.innerWidth <= 767) ? 0.45 : 0.10;

  const r0 = moon.getBoundingClientRect();
  const overhangPx = r0.width * overhangRatio;
  moon.style.transform = `translateY(-50%) translateX(${-(r0.width - overhangPx)}px)`;

  moon.addEventListener('transitionend', function onMoonSlideEnd(e) {
    if (e.propertyName !== 'transform') return;
    moon.removeEventListener('transitionend', onMoonSlideEnd);

    moon.style.transition = 'transform 0.8s cubic-bezier(0.645, 0.045, 0.355, 1), opacity 1s ease-in';
    moon.style.transform = 'translateY(-50%) translateX(-72vw) scale(2.3)';

    moon.addEventListener('transitionend', function onExpandEnd(ev) {
      if (ev.propertyName !== 'transform') return;
      moon.removeEventListener('transitionend', onExpandEnd);

      const hole = document.getElementById('revealHole');
      const rim = document.getElementById('holeRim');
      hole.style.opacity = '0';
      rim.style.opacity = '0';
      document.getElementById('cstHero').style.backgroundColor = 'transparent';

      console.log('🌙 MOON: Animation complete, starting slideshow...');
      // START SLIDESHOW WITH DELAY TO ENSURE EVERYTHING IS READY
      setTimeout(() => {
        startSlideshow();
      }, 200);

    }, { once: true });
  });

  setTimeout(() => {
    const isPhone = window.innerWidth <= 767;
    const subText = document.getElementById('subText');

    if (isPhone) {
      subText.style.visibility = 'visible';
      subText.style.transform = 'translateX(140vw)';
      subText.style.opacity = '0';
      subText.offsetHeight;
      subText.style.transition =
        'transform 900ms cubic-bezier(0.22,1,0.36,1), opacity 900ms ease-out';
      subText.style.transform = 'translate3d(0,0,0)';
      subText.style.opacity = '1';
      return;
    }
  }, 2500);

}, 100);

// KEEP ALL ORIGINAL EVENT LISTENERS
let resizeTimeout;
window.addEventListener('resize', () => {
  if (resizeTimeout) return;
  resizeTimeout = setTimeout(() => {
    setRealVH();
    resizeTimeout = null;
  }, 100);
}, { passive: true });

window.addEventListener('orientationchange', setRealVH, { passive: true });

document.addEventListener('DOMContentLoaded', () => {
  const mqPhone = window.matchMedia('(max-width: 767px)');
  const imgs = Array.from(document.querySelectorAll('#flashSequence .flash-img'));

  imgs.forEach(img => {
    if (!img.dataset.desktop) {
      img.dataset.desktop = img.getAttribute('src') || '';
      img.dataset.desktopSrcset = img.getAttribute('srcset') || '';
    }
  });

function applyResponsiveImages() {
  imgs.forEach(img => {
    const desktop = img.dataset.desktop || '';

    if (mqPhone.matches) {
      // Mobile: src is already mobile from HTML, do nothing
    } else {
      // Desktop: swap to desktop version
      if (desktop && img.src.indexOf(desktop) === -1) {
        img.src = desktop;
        const deskSet = img.dataset.desktopSrcset || '';
        if (deskSet) img.srcset = deskSet;
      }
    }
  });
}

  applyResponsiveImages();
  mqPhone.addEventListener('change', applyResponsiveImages);
});

document.addEventListener('DOMContentLoaded', () => {
  if (window.innerWidth < 768) return;

  const container = document.getElementById('textContainer');
  const sub = document.querySelector('.sub-text');
  if (!container || !sub) return;

  const onSubDone = (e) => {
    if (e.target !== sub) return;
    requestAnimationFrame(() => container.classList.add('text-centered'));
    sub.removeEventListener('animationend', onSubDone);
  };
  sub.addEventListener('animationend', onSubDone);
});
</script>

</body>
</html>

