<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <style>
        @media (max-width: 767px) {
            .elementor-gallery__container {
                position: relative;
                padding-bottom: 66.67% !important;
                height: 0 !important;
                overflow: hidden;
            }

            .e-gallery-item {
                position: absolute !important;
                top: 0 !important;
                left: 0 !important;
                width: 100% !important;
                height: 100% !important;
                opacity: 0;
                transition: opacity 600ms ease-in-out;
            }

            .e-gallery-item.slideshow-active {
                opacity: 1;
                z-index: 2;
            }

            /* Apply object-position to the actual image */
            .e-gallery-image,
            .e-gallery-item img {
                width: 100% !important;
                height: 100% !important;
                object-fit: cover !important;
                background-position: center top !important;
            }
        }
    </style>
</head>
<body>
<script>
    // Only run on mobile
    if (window.innerWidth <= 767) {

        function initGallerySlideshow(galleryContainer) {
            const items = galleryContainer.querySelectorAll('.e-gallery-item');
            if (items.length === 0) return;

            let currentIndex = 0;
            items[0].classList.add('slideshow-active');

            function nextSlide() {
                items[currentIndex].classList.remove('slideshow-active');
                currentIndex = (currentIndex + 1) % items.length;
                items[currentIndex].classList.add('slideshow-active');
            }

            setInterval(nextSlide, 3000);
        }

        function initAllGalleries() {
            const galleries = document.querySelectorAll('.elementor-gallery__container');
            galleries.forEach(gallery => {
                initGallerySlideshow(gallery);
            });
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initAllGalleries);
        } else {
            initAllGalleries();
        }

        setTimeout(initAllGalleries, 500);
        setTimeout(initAllGalleries, 1000);
    }
</script>
</body>
