/* --- MOBILE TAB FIX --- */

/* Mobile: 2-row tab menu + space to content */
@media (max-width: 768px) {
  /* Scope to Elementor nested tabs */
  .e-n-tabs .e-n-tabs-heading {
    display: grid !important;
    grid-auto-flow: column;              /* fill by column -> always 2 rows */
    grid-template-rows: repeat(2, auto); /* exactly TWO rows */
    gap: 8px 12px;                       /* row-gap, column-gap */
    margin-bottom: 16px;                 /* space between tabs and content */
    width: 100%;
    overflow: visible !important;        /* kill any mobile horizontal scroll */
    white-space: normal !important;      /* allow wrapping */
  }

  .e-n-tabs .e-n-tab-title {
    width: 100%;
    min-width: 0;                        /* let grid shrink nicely */
    padding: 10px 12px;
    text-align: center;
    white-space: normal;                 /* multi-line labels okay */
    line-height: 1.2;
  }

  /* Content doesn't need extra spacing since heading has margin-bottom */
  .e-n-tabs .e-n-tabs-content {
    margin-top: 0;
  }
}

@media (max-width: 768px) {
  /* Make the heading container scrollable horizontally and remove gaps */
  .e-n-tabs-heading {
    display: flex !important;
    gap: 0 !important;       /* remove extra spacing */
    padding: 0 !important;   /* remove container padding */
    margin: 0 !important;    /* remove container margin */
    overflow-x: auto;        /* allow horizontal scroll if needed */
    -webkit-overflow-scrolling: touch; /* smooth scrolling on iOS */
  }

  /* Compact tab buttons */
  .e-n-tab-title {
    margin: 0 !important;      /* remove extra margin */
    padding: 6px 10px !important; /* adjust to fit more tabs */
    flex: 0 0 auto !important; /* prevent shrinking */
    font-size: 12px !important; /* smaller font for mobile */
    white-space: nowrap;        /* prevent line wrapping */
  }

  /* Optional: hide scrollbars visually if needed */
  .e-n-tabs-heading::-webkit-scrollbar {
    height: 4px;
  }
  .e-n-tabs-heading::-webkit-scrollbar-thumb {
    background: rgba(0,0,0,0.2);
    border-radius: 2px;
  }
}
