/* Hide horizontal scrollbar */
body {
    overflow-x: hidden;
}

/* Initial state - paragraphs completely off-screen to the left */
.elementor-element-39dbebf p {
    position: relative;
    left: -100vw;
}

/* Animated state - slide in */
.elementor-element-39dbebf p.slide-in {
    animation: slideFromLeft 1s ease-out forwards;
}

/* Keyframe animation - no opacity change */
@keyframes slideFromLeft {
    from {
        left: -100vw;
    }
    to {
        left: 0;
    }
}

/* Stagger delays for each paragraph */
.elementor-element-39dbebf p:nth-child(1).slide-in {
    animation-delay: 0s;
}

.elementor-element-39dbebf p:nth-child(3).slide-in {
    animation-delay: 0.3s;
}

.elementor-element-39dbebf p:nth-child(5).slide-in {
    animation-delay: 0.6s;
}
</style>

<script>
// Simple scroll detection
window.addEventListener('load', function() {
    const section = document.querySelector('.elementor-element-39dbebf');

    function checkScroll() {
        if (!section) return;

        const rect = section.getBoundingClientRect();
        const isInView = rect.top < window.innerHeight && rect.bottom > 0;

        if (isInView) {
            const paragraphs = section.querySelectorAll('p');
            paragraphs.forEach(p => p.classList.add('slide-in'));
            window.removeEventListener('scroll', checkScroll);
        }
    }

    // Check immediately and on scroll
    checkScroll();
    window.addEventListener('scroll', checkScroll);
});
</script>"},"elements":[],"widgetType":"html"}],"isInner":false}]

