    height: 100% !important;
  }

  /* Fix text cutoff issue - CRITICAL */
  [role="tabpanel"],
  [role="tabpanel"] *,
  .e-grid.e-con-full.e-con.e-child,
  .elementor-element.e-grid.e-con-full.e-con.e-child,
  [role="tabpanel"] .e-grid.e-con-full.e-con.e-child,
