}

body, p, span, div, .elementor-widget-container, .elementor-size-default {
    font-weight: normal !important;
    line-height: 1.3 !important;
}

/* Target all flex containers that are direct children of tab content */
.e-n-tabs-content > .e-con > .e-con.e-flex.e-child {
    --container-widget-height: auto !important;
}

/* Fix text cutoff in tab panels */
.e-n-tabs-content [role="tabpanel"] .e-grid.e-con-full.e-con.e-child,
.e-n-tabs-content [role="tabpanel"] .elementor-element.e-grid.e-con-full.e-con.e-child {
  overflow: visible !important;
