  height: auto !important;
  min-height: auto !important;
}

.e-n-tabs-content [role="tabpanel"] .e-grid .elementor-widget-text-editor {
  overflow: visible !important;
  height: auto !important;
}

@media (max-width:768px){
  /* Force all containers in services tabs to expand */
  [data-custom-tabs="1"] .e-con,
  [data-custom-tabs="1"] .e-con-boxed,
  [data-custom-tabs="1"] .e-con-inner,
  [data-custom-tabs="1"] .e-grid,
  [data-custom-tabs="1"] [role="tabpanel"],
  [data-custom-tabs="1"] [role="tabpanel"] > * {
    min-height: 0 !important;
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
  }
}
@media (max-width: 768px) {
    .elementor-7 .elementor-element.elementor-element-358d4fa.elementor-element {
        --align-self: flex-start;
