}

@media (max-width:768px){
  /* hide the original tabs widget on mobile */
  [data-id="358d4fa"]{ display:none !important; }

  /* accordion styling */
  .services-accordion{ margin:8px 0 16px; }
  .services-accordion details{
    margin: 0 26px 8px;
    border: 1px solid #777;
    background: #fff;
  }
  .services-accordion summary{
    padding:10px 12px;
    cursor:pointer;
    list-style:none;
    font: inherit;
    line-height:1.25;
  }
  .services-accordion summary::-webkit-details-marker{ display:none; }
  .services-accordion .panel{ padding:10px 12px; }

  /* belt-and-braces: nothing inside should clip */
