<body>

<script>
(()=>{
  "use strict";

  const MQ = { mobile: () => matchMedia("(max-width:768px)").matches };

  const SERVICES_IDS = [
    "#e-n-tab-content-561533381", "#e-n-tab-content-561533382", "#e-n-tab-content-561533383",
    "#e-n-tab-content-561533384", "#e-n-tab-content-561533385"
  ];

  const isProjects = w => w.classList.contains("projects-tabs") || w.dataset.projects === "1" || w.querySelector("#e-n-tab-content-1717264751");
  const textOfTab = btn => { const t = btn.querySelector(".e-n-tab-title-text"); return (t ? t.textContent : btn.textContent || "").trim(); };

  // COMPLETE ELEMENTOR TAB OVERRIDE
  function createCustomTabSystem(widget) {
    const tablist = widget.querySelector('.e-n-tabs-heading[role="tablist"]');
    const content = widget.querySelector('.e-n-tabs-content');

    if (!tablist || !content) return;

    // Disable all Elementor event handlers
    const tabs = [...tablist.querySelectorAll('.e-n-tab-title')];
    const panels = [...content.querySelectorAll('[role="tabpanel"]')];

    // Remove all Elementor classes and attributes that trigger animations
    panels.forEach(panel => {
      panel.classList.remove('e-active');
      panel.removeAttribute('aria-hidden');
      panel.style.display = 'none';
    });

    tabs.forEach((tab, index) => {
      tab.setAttribute('aria-selected', index === 0 ? 'true' : 'false');
    });

    // Show first panel by default
    if (panels[0]) {
      panels[0].classList.add('custom-active');
      panels[0].style.display = 'block';
    }

    // Override all click events
    tabs.forEach((tab, tabIndex) => {
      // Remove existing event listeners by cloning the element
      const newTab = tab.cloneNode(true);
      tab.parentNode.replaceChild(newTab, tab);

      // Add our custom click handler
      newTab.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();

        // Update tab states immediately
        tabs.forEach((t, i) => {
          const actualTab = tablist.querySelectorAll('.e-n-tab-title')[i];
          actualTab.setAttribute('aria-selected', i === tabIndex ? 'true' : 'false');
        });

        // Update panel states immediately - NO DELAYS OR ANIMATIONS
        panels.forEach((panel, panelIndex) => {
          if (panelIndex === tabIndex) {
            panel.classList.add('custom-active');
            panel.classList.remove('e-active'); // Remove Elementor class
panel.style.display = 'block';
panel.style.opacity = '1';
panel.style.visibility = 'visible';
panel.style.position = 'static';
panel.style.transform = 'none';
panel.style.maxHeight = 'none';
panel.style.overflow = 'visible';
panel.style.height = 'auto';


          } else {
            panel.classList.remove('custom-active', 'e-active');
            panel.style.display = 'none';
          }
        });

        // Force immediate repaint
        content.offsetHeight;

        return false;
      }, true); // Use capture to override other handlers

      // Prevent any other event handlers
      ['mouseenter', 'mouseover', 'focus', 'pointerenter'].forEach(eventType => {
        newTab.addEventListener(eventType, (e) => {
          e.stopPropagation();
          e.stopImmediatePropagation();
        }, true);
      });
    });

    console.log('Custom tab system installed - Elementor system disabled');
  }

  // Standard dropdown code (unchanged)
  function positionList(list, trigger){
    const r = trigger.getBoundingClientRect();
    list.style.position = "fixed";
    list.style.left = Math.round(r.left) + "px";
    list.style.top  = Math.round(r.top)  + "px";
    list.style.width = Math.round(r.width) + "px";
    list.style.maxHeight = Math.floor(innerHeight * 0.55) + "px";
    list.style.pointerEvents = "auto";
  }

  function buildDropdown(tablist){
    let wrap = tablist.nextElementSibling;
    if(!(wrap && wrap.classList && wrap.classList.contains("cstdrop"))){
      wrap = document.createElement("div");
      wrap.className = "cstdrop";
      wrap.innerHTML = `
        <button class="cstdrop__trigger" type="button" aria-haspopup="listbox" aria-expanded="false">
          <span class="cstdrop__label">Select…</span>
          <span class="cstdrop__chev" aria-hidden="true">↓</span>
        </button>
        <div class="cstdrop__list" role="listbox" hidden></div>`;
      tablist.parentNode.insertBefore(wrap, tablist.nextSibling);
    }
    if (wrap.dataset.inited === "1") return;
    wrap.dataset.inited = "1";

    const trigger = wrap.querySelector(".cstdrop__trigger");
    const labelEl = wrap.querySelector(".cstdrop__label");
    const chev    = wrap.querySelector(".cstdrop__chev");
    const list    = wrap.querySelector(".cstdrop__list");
    const tabs    = [...tablist.querySelectorAll(".e-n-tab-title")];

    const inlineMode = MQ.mobile();

    function rebuild(){
      list.innerHTML = "";
      const selIndex = tabs.findIndex(b => b.getAttribute("aria-selected") === "true");
      const currentIdx = Math.max(0, selIndex);
      labelEl.textContent = textOfTab(tabs[currentIdx]);

      tabs.forEach((btn, i) => {
        if (inlineMode && i === currentIdx) return;
        const b = document.createElement("button");
        b.className = "cstdrop__option";
        b.type = "button";
        b.role = "option";
        b.dataset.index = String(i);
        b.setAttribute("aria-selected", btn.getAttribute("aria-selected") === "true" ? "true" : "false");
        b.textContent = textOfTab(btn);
        list.appendChild(b);
      });
    }
    rebuild();

    const lockBody = on => {
      document.documentElement.style.overflow = on ? "hidden" : "";
      document.body.style.overflow = on ? "hidden" : "";
    };

    function openList(){
      trigger.setAttribute("aria-expanded", "true");
      chev.textContent = "↑";

      if (inlineMode){
        list.hidden = false;
        if (list.parentNode !== wrap) wrap.appendChild(list);
        const tw = trigger.getBoundingClientRect().width;
        list.style.position  = "absolute";
        list.style.left      = "0";
        list.style.top       = "100%";
        list.style.width     = Math.round(tw) + "px";
        list.style.maxHeight = Math.floor(innerHeight * 0.55) + "px";
        list.style.zIndex    = "100000";
        list.style.boxShadow = "0 8px 18px rgba(0,0,0,.12)";
        return;
      }

      const cs = getComputedStyle(trigger);
      list.hidden = false;
      list.style.setProperty("font-family", cs.fontFamily, "important");
      list.style.setProperty("line-height", cs.lineHeight, "important");
      list.style.setProperty("font-weight", cs.fontWeight, "important");

      document.body.appendChild(list);
      positionList(list, trigger);

      const pos = () => positionList(list, trigger);
      list._pos = pos;
      addEventListener("scroll", pos, {passive:true});
      addEventListener("resize", pos, {passive:true});

      list.focus({preventScroll:true});
      lockBody(true);
    }

    function closeList(){
      trigger.setAttribute("aria-expanded", "false");
      chev.textContent = "↓";

      if (inlineMode){
        list.hidden = true;
        return;
      }
      list.hidden = true;
      wrap.appendChild(list);
      if (list._pos){
        removeEventListener("scroll", list._pos);
        removeEventListener("resize", list._pos);
        list._pos = null;
      }
      lockBody(false);
    }

    trigger.addEventListener("click", e => {
      e.stopPropagation();
      trigger.getAttribute("aria-expanded") === "true" ? closeList() : openList();
    });

    document.addEventListener("click", e => {
      if (list.hidden) return;
      if (wrap.contains(e.target) || list.contains(e.target)) return;
      closeList();
    }, true);

    ["wheel","touchmove","pointermove"].forEach(evt =>
      list.addEventListener(evt, e => e.stopPropagation(), {passive:true})
    );

    list.addEventListener("click", e => {
      const opt = e.target.closest(".cstdrop__option");
      if (!opt) return;
      const i = +opt.dataset.index;
      const btn = tabs[i];

      btn.click();
      labelEl.textContent = textOfTab(btn);

      if (inlineMode){
        rebuild();
      } else {
        list.querySelectorAll(".cstdrop__option").forEach(o => o.setAttribute("aria-selected","false"));
        opt.setAttribute("aria-selected","true");
      }

      closeList();
    });

    const mo = new MutationObserver(() => {
      const i = tabs.findIndex(t => t.getAttribute("aria-selected") === "true");
      if (i > -1){
        labelEl.textContent = textOfTab(tabs[i]);
        if (inlineMode){
          rebuild();
        } else {
          const opts = list.querySelectorAll(".cstdrop__option");
          opts.forEach(o => o.setAttribute("aria-selected", "false"));
          const match = [...opts].find(o => +o.dataset.index === i);
          if (match) match.setAttribute("aria-selected", "true");
        }
      }
    });
    tabs.forEach(b => mo.observe(b, {attributes:true, attributeFilter:["aria-selected"]}));

    const toggleHeading = () => {
      MQ.mobile() ? tablist.setAttribute("data-cstdrop-hide","1")
                  : tablist.removeAttribute("data-cstdrop-hide");
    };
    toggleHeading();
    addEventListener("resize", toggleHeading, {passive:true});
  }

  function initDropdowns(){
    if(!MQ.mobile()) return;
    document.querySelectorAll('.e-n-tabs-heading[role="tablist"]').forEach(buildDropdown);
  }

  function markServices(){
    document.querySelectorAll(".elementor-widget-n-tabs, .elementor-widget-tabs").forEach(w=>{
      if(w.dataset.customTabs==="1") return;
      if (SERVICES_IDS.some(sel=>w.querySelector(sel))){
        w.setAttribute("data-custom-tabs","1");
        createCustomTabSystem(w);
      }
    });
  }

function projectsMobileScroll(){
  if(!MQ.mobile()) return;

  // Mark projects tabs but skip services tabs entirely
  document.querySelectorAll(".elementor-widget-n-tabs, .elementor-widget-tabs").forEach(w=>{
    const hasServicesTab = SERVICES_IDS.some(sel=>w.querySelector(sel));
    if(isProjects(w) && !hasServicesTab) w.dataset.projects="1";
  });

  function size(){
    if(!MQ.mobile()) return;
    document.querySelectorAll('[data-projects="1"] .e-n-tabs-content').forEach(content=>{
      const r=content.getBoundingClientRect(); const gap=12;
      const avail=Math.max(160, Math.floor(innerHeight - Math.max(0,r.top) - gap));
      content.style.setProperty("--proj-max", avail+"px");
      const active=content.querySelector('[role="tabpanel"].e-active')||content.querySelector('[role="tabpanel"][aria-hidden="false"]')||content.querySelector('[role="tabpanel"].custom-active');
      if(active){
        active.style.setProperty("max-height", avail+"px", "important");
        active.style.setProperty("overflow-y", "auto", "important");
        active.style.setProperty("-webkit-overflow-scrolling", "touch", "important");
        active.style.setProperty("overscroll-behavior", "contain", "important");
        active.style.setProperty("touch-action", "pan-y", "important");
      }
    });
  }
  size();
  addEventListener("resize",size,{passive:true});
  addEventListener("scroll",size,{passive:true});
  document.addEventListener("click",e=>{
    if(e.target.closest(".cstdrop__trigger")){
      requestAnimationFrame(size);
      setTimeout(size,200);
    }
  },true);
  new MutationObserver(size).observe(document.documentElement,{subtree:true,attributes:true,attributeFilter:["aria-selected","class"]});
}
  function killHover(){
    document
      .querySelectorAll('.elementor-widget-n-tabs .e-n-tab-title, .elementor-widget-tabs .elementor-tab-title')
      .forEach(n=>["mouseenter","mouseover","pointerenter","pointerover"]
        .forEach(evt=>n.addEventListener(evt,e=>e.stopImmediatePropagation(),true)));
  }

  function boot(){
    markServices();
    killHover();
    initDropdowns();
    projectsMobileScroll();
  }

  document.readyState==="loading"
    ? document.addEventListener("DOMContentLoaded",boot)
    : boot();

  new MutationObserver(boot).observe(document.documentElement,{childList:true,subtree:true});

  // Continuously monitor and fix height restrictions on services tabs
if(MQ.mobile()) {
  const observer = new MutationObserver(() => {
    SERVICES_IDS.forEach(id => {
      const panel = document.querySelector(id);
      if (!panel || !panel.classList.contains('custom-active')) return;

      // Force panel and all children to expand
      const allContainers = [panel, ...panel.querySelectorAll('.e-grid, .e-con, .e-con-boxed, .e-con-inner, .e-flex')];
      allContainers.forEach(el => {
        if (el.style.maxHeight && el.style.maxHeight !== 'none') {
          el.style.maxHeight = 'none';
          el.style.height = 'auto';
          el.style.minHeight = '0';
          el.style.overflow = 'visible';
        }
      });
    });
  });

  observer.observe(document.body, {
    attributes: true,
    attributeFilter: ['style'],
    subtree: true
  });
}
})();


</script>
<script>
(function(){
  "use strict";
  if (!matchMedia("(max-width:768px)").matches) return;

  // The original tabs widget
  const widget = document.querySelector('[data-id="358d4fa"]');
  if (!widget) return;

  // Grab titles & panels from the Elementor widget
  const titles = [...widget.querySelectorAll('.e-n-tab-title')];
  const panels = [...widget.querySelectorAll('[role="tabpanel"]')];
  if (!titles.length || titles.length !== panels.length) return;

  // Build a simple <details>/<summary> accordion
  const acc = document.createElement('div');
  acc.className = 'services-accordion';

  titles.forEach((t, i) => {
    const d = document.createElement('details');
    // open the currently-selected tab by default
    if (t.getAttribute('aria-selected') === 'true') d.open = true;

    const s = document.createElement('summary');
    const txt = t.querySelector('.e-n-tab-title-text');
    s.textContent = (txt ? txt.textContent : t.textContent || '').trim();

    const panel = panels[i];
    // Move the real panel content into the accordion so styles apply 1:1
    const wrap = document.createElement('div');
    wrap.className = 'panel';
    wrap.appendChild(panel);

    d.appendChild(s);
    d.appendChild(wrap);
    acc.appendChild(d);

    // optional: keep only one open at a time
    s.addEventListener('click', () => {
      acc.querySelectorAll('details').forEach(el => { if (el !== d) el.open = false; });
    });
  });

  // Mount the accordion near the original widget, but outside any clipping wrapper
  const host =
    document.querySelector('#services') ||
    widget.closest('.elementor-section, .elementor-container, .elementor') ||
    widget.parentNode;

  host.appendChild(acc);

  // Hide the original tabs on mobile (CSS also does this)
  widget.style.display = 'none';
})();
</script>


