				<div class="elementor-widget-container">
					<style>
/* === MARQUEE ANIMATION FOR ALL DEVICES === */

/* Ensure the section and parent containers are full-width */
#clients {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100vh !important;
  min-height: 100vh !important;
  width: 100vw !important;
  max-width: 100vw !important;
  margin-inline: 0 !important;
  padding-inline: 0 !important;
  overflow: hidden !important;
}

#clients .selected-clients-gallery,
#clients .selected-clients-gallery .elementor-widget-container {
  width: 100% !important;
  max-width: 100% !important;
  margin-inline: 0 !important;
  padding-inline: 0 !important;
}

/* Hide the original grid gallery on all devices */
#clients .selected-clients-gallery .elementor-gallery__container {
  display: none !important;
}

/* Marquee wrapper - works on all screen sizes */
#clients .clients-marquee {
  display: none !important;
}

#clients .clients-marquee[data-ready="1"] {
  display: grid !important;
  grid-template-rows: repeat(2, auto) !important;
  gap: 16px !important;
  overflow: hidden;
  width: 100vw !important;
  max-width: 100vw !important;
  padding-inline: 0 !important;
  margin-inline: 0 !important;
  position: relative;
  left: 50%;
  right: 50%;
  margin-left: -50vw !important;
  margin-right: -50vw !important;
}

/* Marquee lanes */
#clients .clients-marquee .lane {
  display: flex !important;
  gap: 24px;
  width: max-content !important;
  will-change: transform;
  animation: clients-scroll var(--speed, 36s) linear infinite !important;
  backface-visibility: hidden;
  transform: translateZ(0);
}

#clients .clients-marquee .lane.reverse {
  animation-direction: reverse !important;
}

/* Logo tiles - responsive sizing */
#clients .clients-marquee .logo,
#clients .clients-marquee .e-gallery-image.logo {
  width: clamp(80px, 10vw, 140px) !important;
  aspect-ratio: 1 / 1;
  flex: 0 0 auto;
  background-size: cover !important;
  background-position: center !important;
  border-radius: 8px;
  transition: transform 0.3s ease;
}

/* Optional hover effect on desktop */
@media (min-width: 769px) {
  #clients .clients-marquee .logo:hover,
  #clients .clients-marquee .e-gallery-image.logo:hover {
    transform: scale(1.05);
  }

  #clients .clients-marquee {
    gap: 20px !important;
  }

  #clients .clients-marquee .lane {
    gap: 28px;
  }
}

/* Mobile adjustments - CENTERED VERTICALLY */
@media (max-width: 768px) {
  #clients .clients-marquee[data-ready="1"] {
    gap: 12px !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
  }

  #clients .clients-marquee .lane {
    gap: 20px;
  }

  #clients .clients-marquee .logo,
  #clients .clients-marquee .e-gallery-image.logo {
    width: clamp(56px, 9vw, 96px) !important;
    border-radius: 6px;
  }
}

/* Animation keyframes */
@keyframes clients-scroll {
  from { transform: translate3d(0, 0, 0); }
  to { transform: translate3d(calc(-1 * var(--distance, 0px)), 0, 0); }
}

/* Respect reduced motion preference */
@media (prefers-reduced-motion: reduce) {
  #clients .clients-marquee .lane {
    animation: none !important;
  }
}
</style>

<script>
(function () {
  function bgFrom(el) {
    // Get background image from inline style
    const inline = el.style?.backgroundImage;
    if (inline && inline !== 'none') return inline;

    // Get background image from computed style
    const cmp = getComputedStyle(el).backgroundImage;
    if (cmp && cmp !== 'none') return cmp;

    // Get from Elementor's data-thumbnail attribute
    const thumb = el.getAttribute('data-thumbnail');
    if (thumb) return `url("${thumb}")`;

    return '';
  }

  function build(container) {
    const items = [...container.querySelectorAll('.e-gallery-image')];
    if (!items.length) return null;

    const marquee = document.createElement('div');
    marquee.className = 'clients-marquee';

    // Split items into two lanes (alternating)
    const laneA = items.filter((_, i) => i % 2 === 0);
    const laneB = items.filter((_, i) => i % 2 === 1);
    const fallback = laneB.length ? laneB : laneA;

    const makeLane = (arr, speed) => {
      const lane = document.createElement('div');
      lane.className = 'lane';
      lane.style.setProperty('--speed', speed + 's');

      // Create logo tiles
      (arr.length ? arr : items).forEach(srcEl => {
        const tile = document.createElement('div');
        tile.className = 'e-gallery-image elementor-gallery-item__image logo';
        const bg = bgFrom(srcEl);
        if (bg) tile.style.backgroundImage = bg;
        lane.appendChild(tile);
      });

      // Duplicate for seamless infinite loop
      [...lane.children].forEach(n => lane.appendChild(n.cloneNode(true)));

      // Calculate distance for perfect loop
      requestAnimationFrame(() => {
        const half = lane.scrollWidth / 2;
        lane.style.setProperty('--distance', half + 'px');
      });

      return lane;
    };

    // Create two lanes with different speeds
    marquee.appendChild(makeLane(laneA, 40)); // Top lane
    const bottom = makeLane(fallback, 45);    // Bottom lane (slightly slower)
    bottom.classList.add('reverse');
    marquee.appendChild(bottom);

    // Insert marquee and mark as ready
    container.insertAdjacentElement('afterend', marquee);
    marquee.setAttribute('data-ready', '1');
    container.classList.add('is-hidden-mobile');

    return marquee;
  }

  function destroy(section) {
    const marquee = section.querySelector('.clients-marquee');
    const container = section.querySelector('.selected-clients-gallery .elementor-gallery__container');
    if (marquee) marquee.remove();
    if (container) container.classList.remove('is-hidden-mobile');
  }

  function init(attempt = 0) {
    const section = document.querySelector('#clients');
    const container = section?.querySelector('.selected-clients-gallery .elementor-gallery__container');

    if (!section || !container) return retry(attempt);
    if (section.dataset.csMarqueeReady === '1') return;

    const tiles = container.querySelectorAll('.e-gallery-image');
    if (!tiles.length) return retry(attempt);

    if (build(container)) section.dataset.csMarqueeReady = '1';
  }

  function retry(attempt) {
    if (attempt >= 12) return;
    setTimeout(() => init(attempt + 1), 250);
  }

  // Initialize on page load
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => init(), { once: true });
  } else {
    init();
  }

  window.addEventListener('load', () => init(), { once: true });

  // Handle resize events
  let resizeTimer;
  window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      const section = document.querySelector('#clients');
      if (!section) return;
      section.dataset.csMarqueeReady = '';
      destroy(section);
      init();
    }, 250);
  });

  // Watch for Elementor changes
  new MutationObserver(() => init()).observe(document.documentElement, {
    childList: true,
    subtree: true
  });
})();
</script>				</div>
