/* ===================== C-STUDIOS LOOP ITEM ===================== */
.e-loop-item {
 --cst-gap: 14px;
 --cst-year-w: 70px;
 --cst-title-min: 160px;
 --cst-img-h: 24vh;
 --cst-ink: #777;
 --cst-ink-active: #333;
 --cst-side: 26px;
 margin: 0;
 padding: 0;
}

/* Prevent clipping */
.e-loop-item,
.e-loop-item .e-con,
.e-loop-item .elementor-widget,
.e-loop-item .elementor-widget-container {
 overflow: visible;
}

/* Zero out spacing */
.e-loop-item .e-con,
.e-loop-item .e-con-inner,
.e-loop-item .elementor-element-populated,
.e-loop-item .elementor-widget,
.e-loop-item .elementor-widget-container,
.e-loop-item .elementor-widget-divider,
.e-loop-item figure,
.e-loop-item .wp-block-gallery,
.e-loop-item .wp-block-columns {
 margin: 0;
 padding: 0;
 gap: 0;
}

/* Kill Elementor grid */
.e-loop-item .e-grid {
 display: block;
 grid-template-columns: none;
 column-gap: 0;
}

/* Row layout */
.e-loop-item .cst-row {
 display: grid;
 grid-template-columns: minmax(var(--cst-title-min), 1fr) var(--cst-year-w) minmax(0, 2fr);
 gap: var(--cst-gap);
 align-items: center;
 padding: 0;
 padding-inline: var(--cst-side);
 line-height: 1.3;
 color: var(--cst-ink);
 transition: color .25s ease;
 z-index: 2;
 text-transform: uppercase;
 box-sizing: border-box;
 width: 100%;
}

.e-loop-item .cst-row * {
 color: inherit;
}

.e-loop-item .cst-col-title {
 font-weight: 600;
 text-align: left;
}

.e-loop-item .cst-col-year {
 text-align: center;
 white-space: nowrap;
}

.e-loop-item .cst-col-desc {
 text-transform: none;
 white-space: normal;
 overflow: visible;
 text-overflow: clip;
 font-size: 0.9em;
 line-height: 1.2;
}

/* Pointer & focus only for expandable rows */
.e-loop-item .cst-row[data-has-content="1"] {
 cursor: pointer;
}

.e-loop-item .cst-row[data-has-content="0"] {
 cursor: default;
 -webkit-tap-highlight-color: transparent;
}

.e-loop-item .cst-row:focus-visible {
 outline: 1px dashed var(--cst-ink-active);
 outline-offset: 2px;
}

/* Hover/open state */
.e-loop-item[data-can-expand="1"].cst-hover,
.e-loop-item[data-can-expand="1"].cst-open {
 --cst-ink: var(--cst-ink-active);
}

/* Divider follows ink color */
.e-loop-item .elementor-widget-divider .elementor-divider,
.e-loop-item .elementor-widget-divider .elementor-divider__text {
 color: var(--cst-ink);
}

.e-loop-item .elementor-widget-divider .elementor-divider-separator,
.e-loop-item .elementor-widget-divider .elementor-divider-separator:before,
.e-loop-item .elementor-widget-divider .elementor-divider-separator:after {
 border-top-color: var(--cst-ink);
}

/* Gallery (desktop/tablet) */
.e-loop-item .cst-gallery-wrap {
 display: none;
 margin: 0;
 z-index: 1;
 position: relative;
}

.e-loop-item.cst-open .cst-gallery-wrap {
 display: block;
}

.e-loop-item .cst-gallery-strip {
 overflow-x: auto;
 overflow-y: hidden;
 display: flex;
 gap: 4px;
 padding: 8px 0;
 scroll-behavior: smooth;
 width: 100%;
 margin: 0;
}

.e-loop-item .cst-gallery-strip img {
 height: var(--cst-img-h);
 width: auto;
 display: block;
 object-fit: cover;
 flex: 0 0 auto;
 border-radius: 0;
 opacity: 0;
 transition: opacity .35s ease;
 will-change: opacity;
}


.e-loop-item .cst-gallery-strip img.is-visible {
 opacity: 1;
}

/* Scrollbar styling */
.e-loop-item .cst-gallery-strip::-webkit-scrollbar {
 height: 8px;
}

.e-loop-item .cst-gallery-strip::-webkit-scrollbar-track {
 background: transparent;
}

.e-loop-item .cst-gallery-strip::-webkit-scrollbar-thumb {
 background-color: #000;
 border-radius: 0;
}

.e-loop-item .cst-gallery-strip {
 scrollbar-color: #000 transparent;
 scrollbar-width: thin;
}

/* Hide originals */
.e-loop-item .cst-hidden-original {
 display: none;
}

/* Prevent text selection & image drag */
.e-loop-item,
.e-loop-item *,
.e-loop-item img {
 user-select: none;
 -webkit-user-select: none;
 -ms-user-select: none;
}

.e-loop-item img {
 -webkit-user-drag: none;
 pointer-events: none;
}


.e-loop-item .cst-gallery-strip img {
 height: var(--cst-img-h);
 width: auto;
 display: block;
 object-fit: cover;
 flex: 0 0 auto;
 border-radius: 0;
 opacity: 1; /* Change from 0 to 1 */
 transition: opacity .35s ease;
}

/* Desktop: 2-line clamps */
@media (min-width: 769px) {
 .e-loop-item {
 --cst-desc-lines: 2;
 --cst-title-lines: 2;
 --cst-desc-lh: 1.2;
 }

 .e-loop-item .cst-row {
 min-height: calc(var(--cst-desc-lines) * 1em * var(--cst-desc-lh));
 align-items: center;
 }

 .e-loop-item .cst-col-desc {
 display: -webkit-box;
 -webkit-box-orient: vertical;
 -webkit-line-clamp: var(--cst-desc-lines);
 line-clamp: var(--cst-desc-lines);
 overflow: hidden;
 line-height: var(--cst-desc-lh);
 }

 .e-loop-item .cst-col-title {
 display: -webkit-box;
 -webkit-box-orient: vertical;
 -webkit-line-clamp: var(--cst-title-lines);
 line-clamp: var(--cst-title-lines);
 overflow: hidden;
 }

 /* Desktop: remove side padding from content, keep on row */
 .e-loop-item .elementor-widget-theme-post-content .elementor-widget-container {
 padding: 0;
 }

 .e-loop-item .cst-gallery-strip img {
 /* ... existing styles ... */
 opacity: 1; /* Change from 0 to 1 */
 /* Remove or comment out the transition if you don't need the fade effect */
}
}

/* ===================== MOBILE ===================== */
@media (max-width: 768px) {
 .e-loop-item {
 --cst-year-w: 56px;
 --cst-img-h: 20vh;
 --cst-side: max(20px, env(safe-area-inset-left));
 }

 /* Title + Year only in row */
 .e-loop-item .cst-row {
 grid-template-columns: 1fr var(--cst-year-w);
 min-height: 15px;
 padding-block: 14px;
 font-size: 1.05em;
 }

 .e-loop-item .cst-col-desc {
 display: none;
 }

 .e-loop-item .cst-col-title,
 .e-loop-item .cst-col-year {
 line-height: 1.25;
 display: flex;
 align-items: center;
 }

 .e-loop-item .cst-col-year {
 font-size: 0.65rem;
 justify-content: flex-end;
 text-align: right;
 }

 /* Never darken by default on mobile */
 .e-loop-item.cst-hover,
 .e-loop-item.cst-open {
 --cst-ink: #777;
 }

 /* Only darken expandable items */
 .e-loop-item[data-can-expand="1"].cst-hover,
 .e-loop-item[data-can-expand="1"].cst-open {
 --cst-ink: var(--cst-ink-active);
 }

 /* Hide desktop gallery strip */
 .e-loop-item .cst-gallery-wrap {
 display: none;
 }

 /* Mobile inline expand */
 .e-loop-item .cst-expand {
 display: none;
 position: relative;
 z-index: 1;
 margin: 0px;
 }

 .e-loop-item.cst-open .cst-expand {
 display: block;
 }

 .e-loop-item .cst-expand-desc {
 text-transform: none;
 line-height: 1.2;
 font-size: 0.65rem;
 margin: 0 0 8px 0;
 padding-inline: var(--cst-side);
 padding-right: calc(var(--cst-year-w) + var(--cst-side) + 10px);
 max-width: min(64ch, 100%);
 overflow-wrap: anywhere;
 word-break: normal;
 hyphens: auto;
 }
.e-loop-item .cst-expand-stage {
 position: relative;
 width: 100vw;
 margin-left: calc(50% - 50vw);
 overflow: hidden;
 background: #fff;
}

.e-loop-item .cst-expand-stage img {
 position: absolute;
 top: 0;
 left: 0;
 right: 0;
 width: 100vw;
 height: auto;
 max-height: none;
 object-fit: contain;
 opacity: 0;
 transition: opacity 1.2s ease;
 -webkit-user-drag: none;
 user-select: none;
 pointer-events: none;
 margin: 0;
 padding: 0;
 display: block;
}

.e-loop-item .cst-expand-stage img.is-active {
 opacity: 1;
}
 .e-loop-item.cst-open .cst-gallery-wrap {
 display: none !important;
 }
}




@media (min-width: 769px) {
 .e-loop-item.cst-open .cst-gallery-wrap {
 display: block !important;
 visibility: visible !important;
 margin: 0 !important;
 padding: 0 !important;
 width: 100vw !important; /* Full viewport width */
 position: relative;

 }

 .e-loop-item .cst-gallery-strip {
 display: flex !important;
 visibility: visible !important;
 overflow-x: auto;
 overflow-y: hidden;
 height: var(--cst-img-h);
 min-height: var(--cst-img-h);
 width: 100% !important;
 gap: 0 !important;
 scroll-behavior: smooth;
 font-size: 0;
 justify-content: flex-start; /* Align images to start */
 }

 .e-loop-item .cst-gallery-strip img {
 visibility: visible !important;
 height: var(--cst-img-h) !important;
 width: auto !important;
 max-width: none !important;
 max-height: var(--cst-img-h) !important;
 display: block !important;
 object-fit: contain !important; /* Change to cover for better fill */
 flex: 0 0 auto !important;
 flex-shrink: 0 !important;
 opacity: 1 !important;
 margin: 0 !important;
 padding: 0 !important;
 border: none !important;
 vertical-align: top;
 }
}
</style>

<script>
(function() {
 'use strict';

 const SEL = {
 item: '.e-loop-item',
 title: '.elementor-widget-theme-post-title .elementor-heading-title, .elementor-widget-theme-post-title a',
 contentWrap: '.elementor-widget-theme-post-content .elementor-widget-container',
 anyTime: 'time[datetime], .elementor-post-info__item--date time, .wp-block-post-date time'
 };

 const mqlMobile = window.matchMedia('(max-width: 768px)');
 const slideTimers = new WeakMap();

 // Utilities
 function getYearText(item) {
 const t = item.querySelector(SEL.anyTime);
 if (t) {
 const raw = t.getAttribute('datetime') || t.textContent || '';
 const d = new Date(raw);
 if (!isNaN(d)) return String(d.getFullYear());
 const m = raw.match(/\b(19|20)\d{2}\b/);
 if (m) return m[0];
 }
 const link = item.querySelector('.elementor-widget-theme-post-title a');
 if (link && link.href) {
 const m = link.href.match(/\/((19|20)\d{2})\//);
 if (m) return m[1];
 }
 return '';
 }

function getImageSrc(img) {
 // Priority 1: data-src (lazy load attribute)
 const dataSrc = img.getAttribute('data-src');
 if (dataSrc && !dataSrc.startsWith('data:')) {
 return dataSrc;
 }

 // Priority 2: Extract first URL from data-srcset
 const dataSrcset = img.getAttribute('data-srcset');
 if (dataSrcset) {
 const match = dataSrcset.match(/(https?:\/\/[^\s]+?)(?:\s+\d+w)?(?:,|$)/);
 if (match && match[1]) return match[1];
 }

 // Priority 3: Extract first URL from srcset
 const srcset = img.getAttribute('srcset');
 if (srcset) {
 const match = srcset.match(/(https?:\/\/[^\s]+?)(?:\s+\d+w)?(?:,|$)/);
 if (match && match[1]) return match[1];
 }

 // Priority 4: currentSrc (if already loaded)
 if (img.currentSrc && !img.currentSrc.startsWith('data:')) {
 return img.currentSrc;
 }

 // Priority 5: src (if not data URI)
 if (img.src && !img.src.startsWith('data:')) {
 return img.src;
 }

 // Fallback
 return img.getAttribute('data-lazy-src') || '';
}

function cloneImage(img) {
 const c = document.createElement('img');
 c.decoding = 'async';
 c.loading = 'eager';
 c.alt = img.alt || '';

 // Get the largest image from srcset
 const srcset = img.getAttribute('data-srcset') || img.getAttribute('srcset');
 let largestSrc = '';

 if (srcset) {
 // Parse srcset and find the largest image (highest width descriptor)
 const sources = srcset.split(',').map(s => {
 const parts = s.trim().split(/\s+/);
 const url = parts[0];
 const width = parts[1] ? parseInt(parts[1]) : 0;
 return { url, width };
 });

 // Sort by width and get the largest
 sources.sort((a, b) => b.width - a.width);
 largestSrc = sources[0]?.url || '';
 }

 // Fallback to getImageSrc if no srcset
 if (!largestSrc) {
 largestSrc = getImageSrc(img);
 }

 c.src = largestSrc;

 // Don't set srcset on cloned images - just use the full-size src
 // This prevents browser from loading smaller versions

 return c;
}

 function hideOriginalDate(firstPara, item) {
 const timeEl = item.querySelector(SEL.anyTime);
 if (!timeEl) return;
 const cols = firstPara ? firstPara.closest('.wp-block-columns') : null;
 if (cols && cols.contains(timeEl)) {
 cols.classList.add('cst-hidden-original');
 return;
 }
 const dateBlock = timeEl.closest('.wp-block-post-date') || timeEl.closest('.wp-block-column');
 if (dateBlock) dateBlock.classList.add('cst-hidden-original');
 }

 // Slideshow
 function startSlideshow(item) {
 const stage = item.querySelector('.cst-expand-stage');
 if (!stage) return;
 const imgs = stage.querySelectorAll('img');
 if (imgs.length <= 1) return;

 stopSlideshow(item);
 let idx = 0;
 const id = setInterval(() => {
 imgs[idx].classList.remove('is-active');
 idx = (idx + 1) % imgs.length;
 imgs[idx].classList.add('is-active');
 }, 700);
 slideTimers.set(item, id);
 }

 function stopSlideshow(item) {
 const id = slideTimers.get(item);
 if (id) {
 clearInterval(id);
 slideTimers.delete(item);
 }
 }

 // Calculate and set stage height based on tallest image
 function calculateStageHeight(expandStage, imageSrcs) {
 let maxHeight = 0;
 let loadedCount = 0;
 const totalImages = imageSrcs.length;

 imageSrcs.forEach((src) => {
 const tempImg = new Image();
 tempImg.onload = function() {
 const vw = window.innerWidth;
 const imgHeight = (this.naturalHeight / this.naturalWidth) * vw;

 if (imgHeight > maxHeight) {
 maxHeight = imgHeight;
 }

 loadedCount++;
 if (loadedCount === totalImages) {
 if (maxHeight > 0) {
 expandStage.style.height = maxHeight + 'px';
 expandStage.style.minHeight = maxHeight + 'px';
 } else {
 expandStage.style.height = 'auto';
 expandStage.style.minHeight = '300px';
 }
 }
 };
 tempImg.onerror = function() {
 loadedCount++;
 if (loadedCount === totalImages) {
 if (maxHeight > 0) {
 expandStage.style.height = maxHeight + 'px';
 expandStage.style.minHeight = maxHeight + 'px';
 } else {
 expandStage.style.height = 'auto';
 expandStage.style.minHeight = '300px';
 }
 }
 };
 tempImg.src = src;
 });
 }

 // Create mobile expand
 function ensureExpand(item) {
 let expand = item.querySelector('.cst-expand');
 if (expand) return expand;

 const row = item.querySelector('.cst-row');
 if (!row) return null;

 const expandDesc = document.createElement('div');
 const expandStage = document.createElement('div');
 expandDesc.className = 'cst-expand-desc';
 expandStage.className = 'cst-expand-stage';

 const rowDesc = row.querySelector('.cst-col-desc');
 if (rowDesc && rowDesc.innerHTML.trim()) {
 expandDesc.innerHTML = rowDesc.innerHTML.trim();
 } else {
 const contentEl = item.querySelector(SEL.contentWrap);
 const p = contentEl ? contentEl.querySelector('p') : null;
